mapper.select:
select
    ,
    m.name member_name,
    b.title book_title,
    b.author book_author,
    b.isbn,
    b.cover_object_key,
    bc.barcode approved_copy_barcode
from borrow_application a
join member m on m.id = a.member_id
join book b on b.id = a.book_id
left join book_copy bc on bc.id = a.approved_copy_id

    and a.id = #{q.id}
    and a.application_type = #{q.applicationType}
    and a.borrow_record_id = #{q.borrowRecordId}
    and a.member_id = #{q.memberId}
    and a.status = #{q.status}
    and m.name like concat('%', #{q.memberName}, '%')
    and a.book_id = #{q.bookId}
    and b.title like concat('%', #{q.bookTitle}, '%')
    and b.isbn like concat('%', #{q.isbn}, '%')
    and a.submitted_at >= #{q.submittedFrom}
    and a.submitted_at <= #{q.submittedTo}
    and a.processed_by = #{q.processedBy}

order by
    case a.application_type when 'RENEW' then 0 else 1 end,
    a.submitted_at asc,
    a.id asc

select 
from borrow_application a
where a.id = #{id}

mapper.update:
update borrow_application
set status = 'EXPIRED',
    version = version + 1,
    updated_at = #{now}
where id = #{id}
  and status = 'PENDING'
  and version = #{version}
  and expires_at <= #{now}

mapper.select:
select 
from borrow_application a
where a.status = 'PENDING' and a.expires_at <= #{now}
order by a.id
limit #{limit}

mapper.update:
update borrow_application
set status = 'CANCELLED',
    version = version + 1,
    updated_at = #{now}
where id = #{id}
  and member_id = #{memberId}
  and status = 'PENDING'
  and expires_at > #{now}
  and version = #{version}

update borrow_application
set status = 'REJECTED',
    processed_at = #{now},
    processed_by = #{processor},
    decision_remark = #{remark},
    version = version + 1,
    updated_at = #{now}
where id = #{id}
  and status = 'PENDING'
  and version = #{version}
